when.condition:
@{
      if (context.Request.Method != "POST" || !context.Request.Headers.GetValueOrDefault("Content-Type", "").StartsWith("application/json")) {
          return false;
      }
      var request = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      var name = (string)request["params"]?["name"];
      return (string)request["method"] == "tools/call" && (name == "validateDocument" || name == "submitProposal");
  }

send-request.set-url:
@{
          var request = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
          var path = (string)request["params"]["name"] == "validateDocument" ? "/validate" : "/proposals";
          return "https://" + context.Request.OriginalUrl.Host + "/${docs_path}" + path;
      }

send-request.set-body:
@{
          var request = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
          var arguments = request["params"]["arguments"] as Newtonsoft.Json.Linq.JObject;
          return (arguments ?? new Newtonsoft.Json.Linq.JObject()).ToString(Newtonsoft.Json.Formatting.None);
      }

return-response.set-body:
@{
          var response = (IResponse)context.Variables["docsJsonResponse"];
          return new Newtonsoft.Json.Linq.JObject(
              new Newtonsoft.Json.Linq.JProperty("jsonrpc", "2.0"),
              new Newtonsoft.Json.Linq.JProperty("id", Newtonsoft.Json.Linq.JToken.Parse((string)context.Variables["docsMcpRequestId"])),
              new Newtonsoft.Json.Linq.JProperty("result", new Newtonsoft.Json.Linq.JObject(
                  new Newtonsoft.Json.Linq.JProperty("isError", response.StatusCode >= 400),
                  new Newtonsoft.Json.Linq.JProperty("content", new Newtonsoft.Json.Linq.JArray(
                      new Newtonsoft.Json.Linq.JObject(
                          new Newtonsoft.Json.Linq.JProperty("type", "text"),
                          new Newtonsoft.Json.Linq.JProperty("text", response.Body.As<string>())
                      )
                  ))
              ))
          ).ToString(Newtonsoft.Json.Formatting.None);
      }
